    const id = (this.state || {}).viewId || null;
    if (id === ((prevState || {}).viewId || null)) return;
    try { window.history.replaceState(window.history.state, '', window.location.pathname + window.location.search + '#' + encodeURIComponent(id || 'lenders')); } catch (e) {}
